import { esc,fmt,dayKey,dateLabel,addDays,options } from '../utils.js';
import { weeklySummary } from './summary.js';
import { weeklyVolume,estimated1RM } from '../training/metrics.js';
import { lineChart,barChart } from './charts.js';
import { heading,stats,button } from '../ui/helpers.js';
export function progressView(state,ui) {
  const week=weeklySummary(state,ui.week),weight=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date));
  const selected=ui.progressExercise||state.exercises[0]?.id;
  const points=state.sessions.map(s=>({date:s.date,values:s.sets.filter(x=>x.exerciseId===selected).map(x=>estimated1RM(x.weight,x.reps)).filter(x=>x!==null)})).filter(x=>x.values.length).map(x=>({date:x.date,value:Math.max(...x.values)})).sort((a,b)=>a.date.localeCompare(b.date));
  const byDate=new Map();for(const p of points)byDate.set(p.date,Math.max(p.value,byDate.get(p.date)||0));
  const exercisePoints=[...byDate].map(([date,value])=>({date,value}));
  return `<div class="toolbar">${button('go-home','Volver a Hoy')}</div>`+heading('','Progreso','Tus registros a lo largo del tiempo.')+
    `<div class="toolbar"><label>Semana del<input id="progress-week" type="date" value="${esc(ui.week)}"></label><span class="help">${esc(dateLabel(ui.week))} — ${esc(dateLabel(week.end))}</span></div>`+
    stats([['Entrenamientos',week.workouts],['Series con récord',week.records],['Días cerca del objetivo',`${week.compliant} / ${week.logged}`]])+
    `<details class="quiet-details" data-view-key="summary"><summary>Cómo leer el resumen</summary><p class="help">Solo cuentan las sesiones terminadas y los días con calorías registradas. Un día cerca del objetivo está dentro de un margen del 10 %. Una serie puede superar varios récords.</p></details><section class="panel"><div class="day-title"><h2>Peso corporal</h2>${button('weight-entry','Registrar peso')}</div>${lineChart(weight.map(w=>({date:w.date,value:w.weight})),'Evolución del peso corporal','kg')}<details data-view-key="weights"><summary>Registros y medidas</summary>${weight.map(w=>`<div class="catalog-row"><div><strong>${esc(dateLabel(w.date))} · ${fmt(w.weight,1)} kg</strong><small>${[['waist','Cintura'],['hips','Cadera'],['chest','Pecho']].filter(([k])=>w[k]!==null).map(([k,label])=>label+' '+fmt(w[k],1)+' cm').join(' · ')||'Sin medidas adicionales'}</small></div>${button('weight-entry','Editar',`data-date="${w.date}"`)}</div>`).join('')||'<p class="help">Todavía no hay medidas.</p>'}</details></section><details class="panel" data-view-key="volume"><summary>Carga de entrenamiento por músculo</summary><p class="help">Suma de carga externa × repeticiones (kg). Cada ejercicio cuenta en su grupo principal; las series a 0 kg no añaden volumen.</p>${barChart(weeklyVolume(state.sessions,state.exercises,ui.week,addDays(ui.week,7)))}</details><details class="panel" data-view-key="strength"><summary>Evolución de fuerza</summary><label>Ejercicio<select id="progress-exercise">${options(state.exercises.filter(e=>state.sessions.some(s=>s.sets.some(x=>x.exerciseId===e.id))||e.id===selected).map(e=>[e.id,e.name]),selected)}</select></label>${lineChart(exercisePoints,'Mejor 1RM estimado por fecha','kg')}<p class="help">Epley: peso × (1 + repeticiones / 30); una repetición usa el peso real. Solo cargas positivas y series de 1–12 repeticiones. Es una estimación, no una carga que debas levantar.</p></details><details class="panel" data-view-key="calories"><summary>Historial de calorías</summary><p class="help">Introduce el total diario o marca comidas consumidas en el menú. La entrada manual reemplaza el total del menú para esa fecha.</p><form data-form="nutrition"><div class="fields"><label>Fecha<input type="date" name="date" value="${dayKey()}" max="${dayKey()}" required></label><label>Calorías consumidas<input type="number" name="calories" min="0" max="20000" step="1" inputmode="numeric" required></label></div><button class="secondary">Guardar total diario</button></form><div>${Object.entries(state.nutrition).sort(([a],[b])=>b.localeCompare(a)).slice(0,30).map(([date,n])=>`<div class="catalog-row"><div><strong>${esc(dateLabel(date))} · ${fmt(n.calories)} kcal</strong><small>Objetivo ${fmt(n.target)} kcal · ${n.source==='manual'?'Manual':'Comidas marcadas'}</small></div>${button('delete-nutrition','Quitar',`data-date="${date}"`)}</div>`).join('')}</div></details>`;
}
export function weightForm(entry) {return `<form data-form="weight"><h2>Registrar peso y medidas</h2><div class="fields"><label>Fecha<input type="date" name="date" value="${entry?.date||dayKey()}" max="${dayKey()}" required></label><label>Peso (kg)<input type="number" name="weight" min="25" max="350" step="0.1" value="${entry?.weight||''}" required></label>${[['waist','Cintura'],['hips','Cadera'],['chest','Pecho']].map(([k,label])=>`<label>${label} (cm, opcional)<input type="number" name="${k}" min="20" max="250" step="0.1" value="${entry?.[k]??''}"></label>`).join('')}</div><p class="help">Se conserva un registro por fecha. Guardar una fecha existente la actualiza.</p><div class="toolbar"><button class="primary">Guardar medidas</button>${entry?button('delete-weight','Eliminar registro',`data-date="${entry.date}"`):''}</div></form>`;}
